css:
:scope { width: min(100%, 1360px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 17; grid-row: 1 / span 17; font-family: var(--os-font-heading); font-size: 128.3px; font-weight: 400; line-height: 1.04; letter-spacing: -0.03em; color: var(--os-color-text); }
.gx__i2 { grid-column: 19 / span 6; grid-row: 1 / span 11; font-family: var(--os-font-label); font-size: 16px; font-weight: 400; line-height: 1.8; letter-spacing: -0.02em; color: var(--os-color-text); }
.gx__i3 { grid-column: 19 / span 6; grid-row: 13 / span 7; font-family: var(--os-font-label); font-size: 16px; font-weight: 400; line-height: 1.8; letter-spacing: -0.02em; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 17; grid-row: 22 / span 4; font-family: var(--os-font-label); font-size: 16px; font-weight: 400; line-height: 1.8; letter-spacing: -0.02em; color: var(--os-color-text); }
.gx__i5 { grid-column: 1 / span 8; grid-row: 32 / span 49; aspect-ratio: 446 / 391; }
.gx__i6 { grid-column: 9 / span 8; grid-row: 32 / span 49; aspect-ratio: 446 / 391; }
.gx__i7 { grid-column: 17 / span 8; grid-row: 32 / span 49; aspect-ratio: 446 / 391; }
.gx__i8 { grid-column: 1 / span 8; grid-row: 82 / span 49; aspect-ratio: 446 / 391; }
.gx__i9 { grid-column: 9 / span 8; grid-row: 82 / span 49; aspect-ratio: 446 / 391; }
.gx__i10 { grid-column: 17 / span 8; grid-row: 82 / span 49; aspect-ratio: 446 / 391; }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-heading); font-size: 103px; }
  .gx__i2 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i3 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
}
